#!/usr/bin/env python3
# Publishes the blog post "The Southern Nicoya Peninsula: A Costa Rican Gem Being Discovered" on the PCR WordPress blog, through WordPress itself (no login needed).
# Preview: python3 blogpost.py      Publish: python3 blogpost.py --aplicar
import base64, subprocess, sys, os
BLOG = '/var/www/propertiesincostarica.com/web/blog/'
if not os.path.exists(BLOG + 'wp-load.php'): raise SystemExit('No encontre WordPress en ' + BLOG)
TITLE = 'The Southern Nicoya Peninsula: A Costa Rican Gem Being Discovered'
CONTENT = base64.b64decode('').decode('utf-8')
print('Titulo: ' + TITLE)
print('Largo del texto: %d caracteres' % len(CONTENT))
if '--aplicar' not in sys.argv:
    print('Vista previa. Para publicar: python3 blogpost.py --aplicar'); raise SystemExit
php = r"""<?php
define('WP_USE_THEMES', false);
require '%swp-load.php';
$t = base64_decode('%s');
$c = base64_decode('%s');
$ex = get_page_by_title($t, OBJECT, 'post');
if ($ex) { echo "YA EXISTE: " . get_permalink($ex->ID) . "\n"; exit; }
$admins = get_users(array('role' => 'administrator', 'number' => 1, 'orderby' => 'ID'));
$id = wp_insert_post(array('post_title' => $t, 'post_content' => $c, 'post_status' => 'publish', 'post_author' => $admins ? $admins[0]->ID : 1, 'post_type' => 'post'), true);
if (is_wp_error($id)) { echo "ERROR: " . $id->get_error_message() . "\n"; exit(1); }
echo "PUBLICADO: " . get_permalink($id) . "\n";
""" % (BLOG, base64.b64encode(TITLE.encode()).decode(), base64.b64encode(CONTENT.encode()).decode())
open('/tmp/blogpost.php', 'w').write(php)
r = subprocess.run(['php', '/tmp/blogpost.php'], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, universal_newlines=True)
print(r.stdout[-1500:])
